package clyvr.view;
import clyvr.controller.*;import clyvr.model.Entities.*;import clyvr.ui.*;import javax.swing.*;import java.awt.*;import java.util.*;
public class DoctorManagementView extends JPanel {
 public DoctorManagementView(AppController app){super(new BorderLayout());JPanel p=ViewSupport.page("Doctors  >  Doctor Management","Administrator controls · add doctors and permanently remove eligible accounts");JButton back=Theme.secondary("← Back to Doctors");back.setAlignmentX(Component.LEFT_ALIGNMENT);back.addActionListener(e->app.navigate("Doctors"));p.add(back);Theme.space(p,12);JButton add=Theme.button("+ Add doctor");add.addActionListener(e->{JTextField first=Theme.field(),last=Theme.field();JComboBox<String> specialty=new JComboBox<>(clyvr.model.ClinicStore.SERVICES);JPanel form=new JPanel(new GridLayout(0,1,3,5));form.add(new JLabel("First name"));form.add(first);form.add(new JLabel("Last name"));form.add(last);form.add(new JLabel("Specialty"));form.add(specialty);if(JOptionPane.showConfirmDialog(this,form,"Add doctor",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){String nameError=clyvr.security.Validator.firstError(clyvr.security.Validator.name("First name",first.getText()),clyvr.security.Validator.name("Last name",last.getText()));if(nameError!=null){app.error(nameError);return;}Doctor d=app.store.addDoctor(first.getText().trim(),last.getText().trim(),(String)specialty.getSelectedItem());app.info("Added "+app.store.doctorName(d.id)+". Username: "+app.store.user(d.userId).username+" / Password: doctor123");app.refresh();}});p.add(add);Theme.space(p,17);
  for(Doctor d:new ArrayList<>(app.store.doctors)){JButton remove=Theme.secondary("Remove permanently");remove.addActionListener(e->{if(!app.confirm("Permanently remove "+app.store.doctorName(d.id)+"? Active bookings must be resolved first."))return;try{app.store.removeDoctor(d.id);app.info("Doctor account permanently removed; historical appointments are retained.");app.refresh();}catch(Exception ex){app.error(ex.getMessage());}});ViewSupport.line(p,app.store.doctorName(d.id),d.specialty,remove);}add(ViewSupport.wrap(p));}
}
